local RobloxCSharp = _G.RobloxCSharp or {}
-- Generated by CSharp.lua Compiler
local System = _G.System or require(game:GetService("ReplicatedStorage"):WaitForChild("CoreSystem"))
local ArrayObject = System.Array(System.Object)
local Roblox
local RobloxCSharpEntities
local ListHero
System.import(function (out)
  Roblox = out.Roblox
  RobloxCSharpEntities = RobloxCSharp.Entities
  ListHero = System.List(RobloxCSharpEntities.Hero)
end)
System.namespace("RobloxCSharp.Server", function (namespace)
  -- Главный сервер: регистрирует игроков и создает для них героев
  namespace.class("MainServer", function (namespace)
    local heroList, Init, OnPlayerConnected, SpawnHeroForPlayer, static
    static = function (this)
      heroList = ListHero()
    end
    Init = function ()
      System.Console.WriteLine("=================================================")
      System.Console.WriteLine("[СЕРВЕР C#] Запуск игрового сервера с C# Героями!")
      System.Console.WriteLine("=================================================")

      -- 1. Слушаем подключение новых игроков
      Roblox.Game.Players.PlayerAdded:Connect(function (playerInstance)
        local player = System.cast(Roblox.Player, playerInstance)
        OnPlayerConnected(player)
      end)

      -- 2. Обрабатываем игроков, которые уже есть на сервере
      local currentPlayers = System.cast(ArrayObject, Roblox.Game.Players:GetPlayers())
      if currentPlayers ~= nil then
        for _, p in System.each(currentPlayers) do
          if p ~= nil then
            OnPlayerConnected(System.cast(Roblox.Player, p))
          end
        end
      end

      System.Console.WriteLine("[СЕРВЕР C#] Сервер готов к игре!")
    end
    OnPlayerConnected = function (player)
      if player == nil then
        return
      end
      System.Console.WriteLine("[СЕРВЕР C#] Подключился игрок: " .. System.toString(player.Name))

      -- Слушаем появление персонажа в игре
      player.CharacterAdded:Connect(function (characterInstance)
        local character = System.cast(Roblox.Model, characterInstance)
        SpawnHeroForPlayer(player, character)
      end)

      -- Если персонаж уже загрузился
      if player.Character ~= nil then
        SpawnHeroForPlayer(player, player.Character)
      end
    end
    SpawnHeroForPlayer = function (player, character)
      local humanoidInstance = character:FindFirstChild("Humanoid", false)
      local humanoid = System.cast(Roblox.Humanoid, humanoidInstance)

      if humanoid == nil then
        System.Console.WriteLine("[СЕРВЕР C#] Предупреждение: Humanoid не найден у " .. System.toString(player.Name))
        return
      end

      -- Создаем экземпляр Героя-Прыгуна (SuperJumperHero)
      local newHero = RobloxCSharpEntities.SuperJumperHero(player, character, humanoid)

      -- Инициализируем героя (свойства, интерфейс, аура, прыжок)
      newHero:Initialize()

      -- Сохраняем в список
      heroList:Add(newHero)
    end
    return {
      Init = Init,
      static = static
    }
  end)
end)

return true
